//! Mordred parity test.
//!
//! Compares FerrumChem's Mordred-derived descriptors against the original
//! Mordred 1.2.0 (`tests/data/mordred_parity_reference.csv`, generated by
//! `scripts/generate_mordred_reference.py`): `Radius`, `Diameter`, `Zagreb2`,
//! `ATS0pe..ATS8pe`, `ATS0v..ATS8v`, `BCUTpe-1l/h`, `BCUTv-1l/h`. Values Mordred
//! reports as missing are stored as `nan` and must be NaN in FerrumChem too.
//! Mechanics and baseline handling are the same as in `rdkit_parity.rs`;
//! known deviations are tracked in `tests/data/mordred_parity_baseline.tsv`.
//!
//! ```text
//! FERRUM_UPDATE_PARITY_BASELINE=1 cargo test -p ferrum_core --release --test mordred_parity
//! FERRUM_PARITY_VERBOSE=1 cargo test -p ferrum_core --release --test mordred_parity -- --nocapture
//! ```

mod common;

#[test]
fn mordred_parity() {
    common::parity::run_parity("Mordred", "mordred_parity_reference.csv", "mordred_parity_baseline.tsv");
}
